using AcxiomCrm.Data;using AcxiomCrm.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace AcxiomCrm.Controllers.Api;
[ApiController,Route("api/customers"),Authorize]public class CustomersApiController:ControllerBase{private readonly ApplicationDbContext _db;public CustomersApiController(ApplicationDbContext db)=>_db=db;
[HttpGet]public async Task<IActionResult>Get()=>Ok(await _db.Customers.AsNoTracking().Select(x=>new{x.CustomerId,x.CustomerCode,x.CustomerName,x.Email,x.Phone,x.CompanyName,x.Status,x.CreatedDate}).ToListAsync());
[HttpGet("{id:int}")]public async Task<IActionResult>Get(int id){var x=await _db.Customers.AsNoTracking().Where(x=>x.CustomerId==id).Select(x=>new{x.CustomerId,x.CustomerCode,x.CustomerName,x.Email,x.Phone,x.CompanyName,x.Address,x.City,x.State,x.Status,x.CreatedDate}).FirstOrDefaultAsync();return x==null?NotFound():Ok(x);}
[HttpPost]public async Task<IActionResult>Post(Customer x){if(!ModelState.IsValid)return ValidationProblem(ModelState);if(await _db.Customers.AnyAsync(c=>c.Email==x.Email||c.Phone==x.Phone))return Conflict(new{message="Email or phone already exists."});x.CustomerCode="CUS-"+Guid.NewGuid().ToString("N")[..8].ToUpper();x.CreatedDate=DateTime.UtcNow;_db.Add(x);await _db.SaveChangesAsync();return CreatedAtAction(nameof(Get),new{id=x.CustomerId},new{x.CustomerId,x.CustomerCode,x.CustomerName,x.Email,x.Phone,x.CompanyName,x.Status});}
[HttpPut("{id:int}")]public async Task<IActionResult>Put(int id,Customer x){if(id!=x.CustomerId)return BadRequest();if(!ModelState.IsValid)return ValidationProblem(ModelState);var old=await _db.Customers.FindAsync(id);if(old==null)return NotFound();if(await _db.Customers.AnyAsync(c=>c.CustomerId!=id&&(c.Email==x.Email||c.Phone==x.Phone)))return Conflict(new{message="Email or phone already exists."});old.CustomerName=x.CustomerName;old.Email=x.Email;old.Phone=x.Phone;old.CompanyName=x.CompanyName;old.Address=x.Address;old.City=x.City;old.State=x.State;old.Status=x.Status;await _db.SaveChangesAsync();return Ok(new{old.CustomerId,old.CustomerCode,old.CustomerName,old.Email,old.Phone,old.Status});}
[HttpDelete("{id:int}")]public async Task<IActionResult>Delete(int id){var x=await _db.Customers.FindAsync(id);if(x==null)return NotFound();_db.Remove(x);await _db.SaveChangesAsync();return NoContent();}}
